'use client'

import { type DocsConfig, useDocsConfig } from '@duck-docs/context'
import type { SidebarNavItem } from '@duck-docs/types/nav'
import { cn } from '@gentleduck/libs/cn'
import { ChevronRight } from 'lucide-react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import * as React from 'react'

export interface DocsSidebarNavProps {
  config?: DocsConfig
}

export function DocsSidebarNav({ config }: DocsSidebarNavProps) {
  const pathname = usePathname()
  const fallbackConfig = useDocsConfig()
  const resolvedConfig = config ?? fallbackConfig

  const items = pathname?.startsWith('/charts') ? resolvedConfig.chartsNav : resolvedConfig.sidebarNav

  return (
    items?.length && (
      <div className="flex w-full flex-col">
        {items.map((item, index) => (
          <CategoryItem item={item} key={index} pathname={pathname} />
        ))}
      </div>
    )
  )
}

// Memoized category component to prevent unnecessary re-renders
const CategoryItem = ({ item, pathname }: { item: SidebarNavItem; pathname: string | null }) => {
  return (
    <div className="mb-2 flex flex-col gap-1">
      <div className="flex h-[36px] w-full items-center justify-between text-start font-semibold text-sm [&>div]:w-full [&>div]:justify-between">
        {item.title}
        {item.label && (
          <span className="bg- ml-2 rounded-md px-1.5 py-0.5 font-normal text-[#000000] text-sm leading-none no-underline group-hover:no-underline">
            {item.label}
          </span>
        )}
      </div>
      <div className="border-l">
        {item?.items?.length && (
          <DocsSidebarNavItems accordionDefault={Boolean(item.collapsible)} items={item.items} pathname={pathname} />
        )}
      </div>
    </div>
  )
}

interface DocsSidebarNavItemsProps {
  items: SidebarNavItem[]
  pathname: string | null
  className?: string
  depth?: number
  accordionDefault?: boolean
}

export function DocsSidebarNavItems({
  items,
  pathname,
  className,
  depth = 0,
  accordionDefault = false,
}: DocsSidebarNavItemsProps) {
  return (
    items?.length && (
      <ul className={cn(depth > 0 && 'ml-3 border-l', className)}>
        {items.map((item, index) => (
          <DocsSidebarNavItem
            accordionDefault={accordionDefault}
            depth={depth}
            item={item}
            key={index}
            pathname={pathname}
          />
        ))}
      </ul>
    )
  )
}

export function DocsSidebarNavItem({
  item,
  pathname,
  depth = 0,
  accordionDefault = false,
}: {
  item: SidebarNavItem
  pathname: string | null
  depth?: number
  accordionDefault?: boolean
}) {
  const hasChildren = Boolean(item.items?.length)
  const isAccordionItem = hasChildren && Boolean(item.collapsible ?? accordionDefault)
  const isActive = Boolean(
    pathname &&
      item.href &&
      (pathname === item.href || (item.href !== '/docs' && pathname.startsWith(`${item.href}/`))),
  )
  const [isOpen, setIsOpen] = React.useState(() => {
    if (!isAccordionItem) return true
    return isActive || Boolean(item.defaultOpen)
  })

  React.useEffect(() => {
    if (isAccordionItem && isActive) {
      setIsOpen(true)
    }
  }, [isAccordionItem, isActive])

  if (item.href && !item.disabled) {
    return (
      <li className={cn(isActive && 'border-primary border-l')}>
        <div className="flex items-center">
          <Link
            className={cn(
              'group flex w-full items-center border-primary px-4 py-1 font-medium text-sm focus-visible:border-l focus-visible:outline-none',
              depth > 0 && 'px-3',
              isActive ? 'font-medium text-foreground' : 'text-muted-foreground',
            )}
            href={item.href}
            scroll
            rel={item.external ? 'noreferrer' : ''}
            target={item.external ? '_blank' : ''}>
            {item.title}
            {item.label && (
              <span className="ml-2 rounded-md bg-primary px-1.5 py-0.5 font-medium text-accent text-xs leading-none no-underline group-hover:no-underline">
                {item.label}
              </span>
            )}
          </Link>
          {isAccordionItem && (
            <button
              aria-expanded={isOpen}
              aria-label={`Toggle ${item.title}`}
              className="mr-1 inline-flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
              onClick={(event) => {
                event.preventDefault()
                event.stopPropagation()
                setIsOpen((open) => !open)
              }}
              type="button">
              <ChevronRight className={cn('size-3 transition-transform', isOpen && 'rotate-90')} />
            </button>
          )}
        </div>
        {hasChildren &&
          (isAccordionItem ? (
            <AnimatedHeightCollapse open={isOpen}>
              <DocsSidebarNavItems
                accordionDefault={accordionDefault}
                depth={depth + 1}
                items={item.items ?? []}
                pathname={pathname}
              />
            </AnimatedHeightCollapse>
          ) : (
            <DocsSidebarNavItems
              accordionDefault={accordionDefault}
              depth={depth + 1}
              items={item.items ?? []}
              pathname={pathname}
            />
          ))}
      </li>
    )
  }

  return (
    <li>
      <div className="flex items-center">
        <span
          className={cn(
            'flex w-full cursor-not-allowed items-center rounded-md p-2 text-muted-foreground hover:underline',
            depth > 0 && 'px-3',
          )}>
          {item.title}
          {item.label && (
            <span className="ml-2 rounded-md bg-muted px-1.5 py-0.5 text-muted-foreground text-sm leading-none no-underline group-hover:no-underline">
              {item.label}
            </span>
          )}
        </span>
        {isAccordionItem && (
          <button
            aria-expanded={isOpen}
            aria-label={`Toggle ${item.title}`}
            className="mr-1 inline-flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            onClick={() => {
              setIsOpen((open) => !open)
            }}
            type="button">
            <ChevronRight className={cn('size-3 transition-transform', isOpen && 'rotate-90')} />
          </button>
        )}
      </div>
      {hasChildren &&
        (isAccordionItem ? (
          <AnimatedHeightCollapse open={isOpen}>
            <DocsSidebarNavItems
              accordionDefault={accordionDefault}
              depth={depth + 1}
              items={item.items ?? []}
              pathname={pathname}
            />
          </AnimatedHeightCollapse>
        ) : (
          <DocsSidebarNavItems
            accordionDefault={accordionDefault}
            depth={depth + 1}
            items={item.items ?? []}
            pathname={pathname}
          />
        ))}
    </li>
  )
}

function AnimatedHeightCollapse({ open, children }: { open: boolean; children: React.ReactNode }) {
  return (
    <div
      aria-hidden={!open}
      className={cn(
        'grid transition-[grid-template-rows] duration-300 ease-(--duck-motion-ease)',
        open ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]',
      )}>
      <div className={cn('overflow-hidden', !open && 'invisible')}>{children}</div>
    </div>
  )
}
